final class SubscriptionsScreen {
 final MainActivity a;final Book book;SubscriptionsScreen(MainActivity a){this.a=a;book=new Book(a.manager);}
 void open(){renderSafe();a.load("subs-sync",()->book.sync(),this::updated);JSONObject cloud=CloudMonitor.snapshot(a.manager);if(CloudPublisher.config(a.manager)!=null)a.loadIfDue("cloud",Refresher.CLOUD,cloud==null?0:cloud.optLong("checked"),()->CloudMonitor.check(a.manager,"subscription"),this::updated);}
 // Quick refresh: tidy favorites locally and re-check the fixed subscription; downloading every favorite stays in the menu.
 void quickRefresh(){a.load("subs-sync",()->book.sync(),this::updated);if(CloudPublisher.config(a.manager)!=null)a.load("cloud",()->CloudMonitor.check(a.manager,"subscription"),this::updated);renderSafe();}
 void updated(){if(a.tab.equals("订阅"))a.renderLater("subs",()->a.manager.data.opt("favorites")+"|"+a.manager.data.opt("cloud_monitor")+"|"+a.loading("subs-check"),this::renderSafe);}
 void renderSafe(){try{render();}catch(Exception e){a.card("订阅暂时无法读取","请点击顶部刷新重试。");}}
 void checkAll(){a.toast("正在后台检查全部订阅");a.load("subs-check",()->{JSONArray all=book.all();for(int i=0;i<all.length();i++){JSONObject f=all.getJSONObject(i);if(f.optBoolean("hidden"))continue;synchronized(a.manager){book.check(f,false);}a.runOnUiThread(this::updated);}},this::updated);}
 void render()throws Exception{
  int y=a.scroll().getScrollY();a.body.removeAllViews();JSONObject fixed=CloudPublisher.config(a.manager),state=CloudMonitor.snapshot(a.manager);LinearLayout pinned=a.card("固定订阅","");if(fixed==null){pinned.addView(a.label("尚未配置固定入口；配置后换服务器可继续使用同一个订阅地址。",14,a.MUTED));a.button(pinned,"配置 Cloudflare 固定入口",()->new CloudScreen(a).edit());}else{boolean fresh=state!=null&&CloudState.fresh(state.optLong("checked"),System.currentTimeMillis()),ok=state!=null&&CloudState.healthy(state.optInt("health"),state.optInt("admin"),state.optInt("subscription"));a.badge(pinned,CloudState.summary(true,state==null?0:state.optLong("checked"),System.currentTimeMillis(),state==null?0:state.optInt("health"),state==null?0:state.optInt("admin"),state==null?0:state.optInt("subscription")),fresh&&ok);if(state!=null&&state.optInt("admin")==200)pinned.addView(a.tnum(a.label(state.optBoolean("published")?state.optInt("nodes")+" 个节点 · 发布于 "+Core.shortTime(state.optString("updated_at")):"尚未发布配置",12,a.MUTED)));a.pair(pinned,"导入到 FlClash",MainActivity.Tone.PRIMARY,()->SubscriptionActions.flclash(a,CloudScreen.record(fixed)),"监视与发布",MainActivity.Tone.PLAIN,()->new CloudScreen(a).open());}
  a.section("订阅收藏","");LinearLayout top=a.card("","");top.setPadding(a.dp(4),a.dp(4),a.dp(4),a.dp(4));a.pair(top,"＋ 添加订阅",MainActivity.Tone.PLAIN,()->edit(null),"管理",MainActivity.Tone.PLAIN,()->a.menu("订阅管理",new String[]{"检查全部订阅","多节点合并 / 发布","固定入口详情","后台提醒设置"},()->checkAll(),()->mergePicker(),()->new CloudScreen(a).open(),()->a.page("设置")));
  JSONArray all=book.all();int count=0;for(int i=0;i<all.length();i++){JSONObject f=all.getJSONObject(i);if(f.optBoolean("hidden"))continue;count++;LinearLayout c=a.card(f.optString("name","订阅"),"");String st=book.status(f);a.pill(c,st,tone(st));c.addView(a.tnum(a.label("最近检查 "+Core.shortTime(f.optString("checked")),12,a.MUTED)));a.pair(c,"导入到 FlClash",MainActivity.Tone.PRIMARY,()->SubscriptionActions.flclash(a,newRecord(f)),"更多",MainActivity.Tone.PLAIN,()->a.menu(f.optString("name","订阅操作"),new String[]{"完整节点检测","查看检测报告","用于电脑 Clash Verge","复制订阅地址","重命名 / 修改链接","移出收藏"},()->test(f),()->a.message(f.optString("report","尚未检测")),()->SubscriptionActions.desktop(a,newRecord(f)),()->a.copySubscription(newRecord(f)),()->edit(f),()->remove(f)));}
  if(count==0)a.empty(2,"暂无收藏","本机部署自动收录；也可添加已有订阅链接。","添加订阅",()->edit(null));a.helpCard("导入、发布与检测的区别","导入会打开代理客户端添加订阅，不会删除已有配置，也不能读取客户端当前选择。发布会修改你自己的 Cloudflare 固定订阅内容。\n订阅失败不一定是服务器失效；后台只检查固定入口、订阅下载和已关联实例，完整端口与出口检测需手动执行，不开关手机 VPN。");a.restoreScroll(y);
 }
 int tone(String status){return status.contains("已删除")||status.contains("失败")?a.DANGER:status.contains("未通过")||status.contains("异常")||status.contains("待")?a.AMBER:status.contains("通过")||status.contains("可下载")?a.GREEN:a.MUTED;}
 void remove(JSONObject f){new AlertDialog.Builder(a).setTitle("移出收藏？").setMessage("仅移除此收藏，不删除云端服务器。").setNegativeButton("取消",null).setPositiveButton("移除",(d,w)->a.task("移出收藏…",()->{f.put("hidden",true);a.manager.save();a.ui(()->render());})).show();}
 JSONObject newRecord(JSONObject f){try{return book.importRecord(f);}catch(Exception e){return new JSONObject();}}
 void edit(JSONObject f){LinearLayout p=new LinearLayout(a);p.setOrientation(1);p.setPadding(a.dp(24),0,a.dp(24),a.dp(12));EditText name=a.field(p,"中文名称",f==null?"":f.optString("name"),false),url=a.field(p,"订阅 URL",f==null?"":f.optString("url"),true);AlertDialog d=new AlertDialog.Builder(a).setTitle(f==null?"添加收藏":"编辑收藏").setView(p).setNegativeButton("取消",null).setPositiveButton("保存",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String n=name.getText().toString(),u=url.getText().toString();try{SubscriptionLinks.valid(u.trim());if(n.trim().isEmpty()){name.setError("请输入名称");return;}}catch(Exception e){url.setError("请输入 HTTP/HTTPS 订阅地址");return;}d.dismiss();a.task("保存加密收藏…",()->{book.edit(f,n,u);a.ui(()->render());});}));d.show();}
 void test(JSONObject f){if(a.busy){a.message("正在执行其他操作，请稍候。");return;}NodeProbe.cancelled=false;ProgressDialog d=new ProgressDialog(a);d.setTitle("分层检测节点");d.setMessage("依次检查订阅、端口、独立代理出口。可取消，网络失败不会被判定为 IP 被封。");d.setCancelable(false);d.setButton(-2,"取消检测",(x,w)->NodeProbe.cancel());d.show();a.task("检测目标节点，请稍候…",()->{try{String report=book.check(f,true);a.ui(()->{d.dismiss();render();a.message(report);});}catch(Exception e){a.ui(()->d.dismiss());throw e;}});}
 void mergePicker(){try{List<JSONObject> available=new ArrayList<>();JSONArray all=book.all();for(int i=0;i<all.length();i++){JSONObject f=all.getJSONObject(i);if(!f.optBoolean("hidden")&&!book.deleted(f)&&!f.optBoolean("superseded"))available.add(f);}if(available.isEmpty()){a.message("请先添加订阅。");return;}String[] names=new String[available.size()];for(int i=0;i<names.length;i++)names[i]=available.get(i).optString("name");boolean[] selected=new boolean[names.length];new AlertDialog.Builder(a).setTitle("选择要合并或发布的订阅").setMultiChoiceItems(names,selected,(d,i,v)->selected[i]=v).setNegativeButton("取消",null).setPositiveButton("生成配置",(d,w)->a.task("下载并合并节点…",()->{List<String> labels=new ArrayList<>();List<Map<String,Object>> configs=new ArrayList<>();for(int i=0;i<selected.length;i++)if(selected[i]){labels.add(names[i]);configs.add(Configs.parse(Book.download(available.get(i).getString("url"))));}if(configs.isEmpty())throw new IOException("至少选择一份订阅");Map<String,Object> combined=configs.size()==1?Configs.routing(Configs.parse(a.manager.asset("config.yaml")),configs.get(0)):Configs.merge(Configs.parse(a.manager.asset("config.yaml")),labels,configs);Configs.nodes(combined);File folder=new File(a.getFilesDir(),"exports");folder.mkdirs();File output=new File(folder,"merged-"+UUID.randomUUID()+".yaml");Files.write(output.toPath(),Configs.yaml(combined).getBytes("UTF-8"));a.ui(()->mergeResult(output,combined));})).show();}catch(Exception e){a.message("无法读取收藏列表。");}}
 void mergeResult(File file,Map<String,Object> config){a.enterDetail("合并订阅","订阅",()->renderMerge(file,config));}
 void renderMerge(File file,Map<String,Object> config){LinearLayout c=a.card("合并配置已生成","包含 "+((List)config.get("proxies")).size()+" 个节点。包含私密节点参数，仅分享给可信客户端。");a.pair(c,"保存合并文件",()->{a.pendingExport=file;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/yaml").putExtra(Intent.EXTRA_TITLE,"Vultr-合并节点.yaml");a.startActivityForResult(i,301);},"更多",()->a.menu("合并订阅",new String[]{"分享合并文件","发布到固定订阅入口"},()->{Uri uri=Uri.parse("content://com.yjw.vultr.exports/"+file.getName());Intent i=new Intent(Intent.ACTION_SEND).setType("application/yaml").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("合并配置",uri));a.startActivity(Intent.createChooser(i,"选择可信的文件接收应用"));},()->a.task("更新固定订阅入口…",()->{CloudPublisher.publish(a.manager,new JSONObject(config));a.ui(()->a.toast("发布成功，客户端刷新固定订阅即可",Notice.Kind.SUCCESS));})));}
}
